(6074657, 893911, 110400, '<td valign="top">Not detracting from your picture, but they look emaciated.  Poor cows. (6)</td>', 'Not detracting from your picture, but they look emaciated.  Poor cows. (6)', '2010-06-30 16:55:56.000000', NULL, 1),
(6074660, 894527, 110400, '<td valign="top">Wow...it hurts my eyes.</td>', 'Wow...it hurts my eyes.', '2010-06-30 17:00:29.000000', NULL, 1),
(6074663, 894314, 110400, '<td valign="top">This is genus Capra and not genus Bovine.</td>', 'This is genus Capra and not genus Bovine.', '2010-06-30 17:03:28.000000', NULL, 1),
(6074696, 893938, 114225, '<td valign="top">Possibly the coolest mailbox I have seen in a long time. Other than that, this photo doesn''t carry a lot of interest. Maybe playing around with depth of field, angles, or something to make it more dramatic could have helped.</td>', 'Possibly the coolest mailbox I have seen in a long time. Other than that, this photo doesn''t carry a lot of interest. Maybe playing around with depth of field, angles, or something to make it more dramatic could have helped.', '2010-06-30 17:39:17.000000', NULL, 1),
(6074701, 894310, 114225, '<td valign="top">Vibrant colors on a fun mural. I wonder if it could have been nice to work with the branches to create a framing effect, instead of having the branch cut through the middle of your subject.</td>', 'Vibrant colors on a fun mural. I wonder if it could have been nice to work with the branches to create a framing effect, instead of having the branch cut through the middle of your subject.', '2010-06-30 17:40:30.000000', NULL, 1),
(6074702, 893498, 114225, '<td valign="top">These guys look ready to charge! Unfortunately, this image seems like it could have been better with sharper focus, and a negative exposure adjustment (so that you weren''t blowing out so many highlights).</td>', 'These guys look ready to charge! Unfortunately, this image seems like it could have been better with sharper focus, and a negative exposure adjustment (so that you weren''t blowing out so many highlights).', '2010-06-30 17:41:28.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6074705, 894378, 114225, '<td valign="top">These cow statues are great. Some things I would suggest for the photo: maybe choose an angle that doesn''t show the building on the left, and try to get less reflections bouncing around (maybe on a cloudy day or when the sun is low in the sky).</td>', 'These cow statues are great. Some things I would suggest for the photo: maybe choose an angle that doesn''t show the building on the left, and try to get less reflections bouncing around (maybe on a cloudy day or when the sun is low in the sky).', '2010-06-30 17:42:58.000000', NULL, 1),
(6074708, 894111, 114225, '<td valign="top">Great catch! I hope that bird didn''t leave the same present they always leave on my cars! I think the photo could have been slightly better if the background cow wasn''t visible (obviously, you couldn''t have reshot without the bird moving, so no points off), and if the front grass wasn''t so bright.</td>', 'Great catch! I hope that bird didn''t leave the same present they always leave on my cars! I think the photo could have been slightly better if the background cow wasn''t visible (obviously, you couldn''t have reshot without the bird moving, so no points off), and if the front grass wasn''t so bright.', '2010-06-30 17:45:21.000000', NULL, 1),
(6074710, 893972, 114225, '<td valign="top">I see what you were going for with showing the whole scene, but I think this could have been a more powerful shot if more focus was given to one cow (maybe using the rule of thirds).</td>', 'I see what you were going for with showing the whole scene, but I think this could have been a more powerful shot if more focus was given to one cow (maybe using the rule of thirds).', '2010-06-30 17:46:10.000000', NULL, 1),
(6074713, 894346, 114225, '<td valign="top">Good scene. Hard to get  good fading background with cows, it seems. This photo relaly draws your attention to the cow.</td>', 'Good scene. Hard to get  good fading background with cows, it seems. This photo relaly draws your attention to the cow.', '2010-06-30 17:52:42.000000', NULL, 1),
(6074714, 894317, 114225, '<td valign="top">Great setup and perspective. Too bad that other cow but it''s butt in your shot :)</td>', 'Great setup and perspective. Too bad that other cow but it''s butt in your shot :)', '2010-06-30 17:53:58.000000', NULL, 1),
(6074717, 894371, 114225, '<td valign="top">The black and white with graininess gives this a real classic feel.</td>', 'The black and white with graininess gives this a real classic feel.', '2010-06-30 17:55:31.000000', NULL, 1),
(6074727, 894284, 114225, '<td valign="top">I like the idea you were going for here, but I feel the photo could have used some improvements:<br/>-I would have cropped out the person (especially sine he has a colorful jacket, he''s really standing out)<br/>-The back/side sunlight is making it so details in the cows'' faces isn''t seen. Maybe a fill flash could have helped, or a reflector.<br/>-I really like how the little cow in the back has his feet in the air :)</td>', 'I like the idea you were going for here, but I feel the photo could have used some improvements:-I would have cropped out the person (especially sine he has a colorful jacket, he''s really standing out)-The back/side sunlight is making it so details in the cows'' faces isn''t seen. Maybe a fill flash could have helped, or a reflector.-I really like how the little cow in the back has his feet in the air :)', '2010-06-30 18:06:23.000000', NULL, 1),
(6074729, 893746, 114225, '<td valign="top">You took a photo, even with this sign in place? For shame! :)</td>', 'You took a photo, even with this sign in place? For shame! :)', '2010-06-30 18:06:42.000000', NULL, 1),
(6074732, 894366, 114225, '<td valign="top">This is making my mouth water. I''m sure you''ll get some low votes from the bovine purists. I am not taking any points off for that, but rather for the lighting/background. You did well in showing the textures, but I think it could have been even better with a diffused light source, and a solid background.</td>', 'This is making my mouth water. I''m sure you''ll get some low votes from the bovine purists. I am not taking any points off for that, but rather for the lighting/background. You did well in showing the textures, but I think it could have been even better with a diffused light source, and a solid background.', '2010-06-30 18:10:25.000000', NULL, 1),
(6074733, 893553, 114225, '<td valign="top">This photo has potential. It''s pretty well composed, and it looks like you got low to the ground to get a straight on shot. However, the focus feels a bit off, and the lighting it really harsh (a lot of blown out background grass). I would suggest for the latter to bump the EV (exposure value) down to maybe -2/3 or -1 to ensure the highlights are not blown out.</td>', 'This photo has potential. It''s pretty well composed, and it looks like you got low to the ground to get a straight on shot. However, the focus feels a bit off, and the lighting it really harsh (a lot of blown out background grass). I would suggest for the latter to bump the EV (exposure value) down to maybe -2/3 or -1 to ensure the highlights are not blown out.', '2010-06-30 18:12:46.000000', NULL, 1),
(6074735, 893911, 114225, '<td valign="top">This is a really great shot overall. I do see a bit of haloing, which is taking away from the photo somewhat (did you convert to HDR?).</td>', 'This is a really great shot overall. I do see a bit of haloing, which is taking away from the photo somewhat (did you convert to HDR?).', '2010-06-30 18:15:55.000000', NULL, 1),
